using System;

// PROGRAM: Pembuktian Value Type vs Reference Type di C#
public struct CoordinateStruct
{
    public int X;
    public int Y;
}

public class CoordinateClass
{
    public int X;
    public int Y;
}

public class Program
{
    public static void Main()
    {
        // 1. Uji Perilaku Struct (Value Type)
        CoordinateStruct s1 = new CoordinateStruct { X = 100, Y = 200 };
        CoordinateStruct s2 = s1; // Copy by value: duplikasi bit independen
        s2.X = 999;

        Console.WriteLine($"[STRUCT] s1.X: {s1.X} (Harus tetap 100)");
        Console.WriteLine($"[STRUCT] s2.X: {s2.X} (Berubah menjadi 999)");

        // 2. Uji Perilaku Class (Reference Type)
        CoordinateClass c1 = new CoordinateClass { X = 100, Y = 200 };
        CoordinateClass c2 = c1; // Copy by reference: menyalin pointer alamat heap
        c2.X = 999;

        Console.WriteLine($"\n[CLASS]  c1.X: {c1.X} (Ikut berubah menjadi 999!)");
        Console.WriteLine($"[CLASS]  c2.X: {c2.X} (999)");

        // TODO: Perhatikan bahwa c1 dan c2 mereferensikan instance objek yang sama persis di Managed Heap!
    }
}

